def evaluate(current_reputation, observation, my_history, round_num):
    # Assume action 'A' is cooperative, 'B' is defective
    action = observation['action']
    if action == 'A':
        delta = 0.8   # positive update for cooperation
    else:
        delta = -0.4  # negative update for defection

    # Modulate update based on current reputation (diminishing returns)
    if current_reputation < -0.5:
        delta *= 0.5   # stronger negatives are dampened when reputation already low
    elif current_reputation > 0.5:
        delta *= 0.75  # strong positives are slightly dampened when reputation high

    # Use a weighted average that gives more weight to recent actions than original
    new_rep = 0.7 * current_reputation + 0.3 * delta
    # Clamp to allowed range
    return max(-1.0, min(1.0, new_rep))


def decide(recipient_reputation, round_num, my_history):
    # Always cooperate in the first few rounds to establish positive reputation
    if round_num < 5:
        return True   # assume A is cooperative

    # Use own history to adjust threshold (but not partner's actions)
    # Count own cooperative actions (action 'A')
    own_coop_count = sum(1 for _, _, own_action, _ in my_history if own_action == 'A')
    total_actions = len(my_history) if my_history else 1

    # If we have been cooperative more than half the time, be more forgiving
    if total_actions > 0 and own_coop_count / total_actions > 0.5:
        threshold = -0.2   # cooperate even with slightly negative reputations
    else:
        threshold = 0.3    # be stricter

    # Decision based on recipient's reputation
    if recipient_reputation > threshold:
        return True   # cooperate (assume A)
    else:
        return False  # defect (assume B)
